int minMeetingRooms(vector<vector<int>>& iv) {
    vector<pair<int,int>> ev; for (auto& v : iv) { ev.push_back({v[0], 1}); ev.push_back({v[1], -1}); }
    sort(ev.begin(), ev.end());   // (t, -1) sorts before (t, +1): ends first
    int cur = 0, best = 0; for (auto& [t, d] : ev) { cur += d; best = max(best, cur); } return best;
}
